// Proposed neutral persisted types, root-owned provider-proof.ts, strict versioned schemas.
type ProofArtifact = Readonly<{schemaVersion:1; hash:string; canonicalPayload:string; createdAt:number}>;
type ProviderCredentialGeneration = Readonly<{schemaVersion:1; providerId:string; revision:number; generationId:string; accountId:string; credentialFingerprint:string; changedAt:number}>;
// Four narrowly scoped ports added to existing ProductionReadPort/WritePort.
getProofArtifact(hash:string): ProofArtifact | null;
getProviderCredentialGeneration(providerId:string): ProviderCredentialGeneration | null;
insertProofArtifact(artifact:ProofArtifact): InsertOutcome<ProofArtifact>;
compareAndSetProviderCredentialGeneration(record:ProviderCredentialGeneration, expectedRevision:number|null): boolean;
// No raw credentials, arbitrary file paths or remote fetch on artifact resolution.
// Existing SogniProviderTransport gets optional account methods; missing => unknown.
readAuthenticatedAccount?(): Promise<{walletAddress:string; subscription:unknown; observedAt:number; connectionId:string}>;
// same cached SDK client invokes account.me() and account.getSubscriptionStatus(); not a second account client.
// C06-PRE actual exported recipe type becomes authoritative (name frozen by its boundary review).
type QuoteRecipeResolver = (read:ProductionReadPort, command:CreateQuoteCommand) => ValidatedMediaRecipe | null;
// Root composer consumes store, provider, exact resolver, reviewed policy and injected clock.
createProductionBudgetComposer(options:{store:ProductionStore; provider:ProviderPort; resolveQuoteRecipe:QuoteRecipeResolver; proofPolicy:ReviewedSubscriptionPolicy|null; now?:()=>number}): {
 composeQuote(command:CreateQuoteCommand):Promise<ProductionQuote>;
 resolveAccountIdentity(providerId:string):Promise<TrustedAccountIdentity>;
 prepareExecutionEvidence(input:{execution:BudgetExecution;budgetQuoteId:string}):Promise<TrustedPreparedExecutionEvidence>;
 currentCredentialBindingId(providerId:string):string|null;
 // B3 createProductionBudgetService and B4 structural callbacks are wired by root runtime.
};
